using System.Text;
using System.Windows;
using System.Windows.Controls;
using D2RBot.GUI.Services;

namespace D2RBot.GUI
{
    public partial class MainWindow : Window
    {
        private BotEngine _botEngine;
        private bool _isRunning = false;

        public MainWindow()
        {
            InitializeComponent();
            _botEngine = new BotEngine();
            _botEngine.OnLogMessage += LogMessage;
            _botEngine.OnStatusChanged += OnStatusChanged;
            _botEngine.OnRunCompleted += OnRunCompleted;
        }

        private void StartBot_Click(object sender, RoutedEventArgs e)
        {
            if (_isRunning)
            {
                LogMessage("Bot is already running!", "WARNING");
                return;
            }

            var route = (RouteCombo.SelectedItem as ComboBoxItem)?.Content.ToString() ?? "Cow Level";
            _botEngine.Start(route);
            _isRunning = true;
            LogMessage($"Bot started - Route: {route}", "INFO");
        }

        private void StopBot_Click(object sender, RoutedEventArgs e)
        {
            if (!_isRunning)
            {
                LogMessage("Bot is not running!", "WARNING");
                return;
            }

            _botEngine.Stop();
            _isRunning = false;
            LogMessage("Bot stopped", "INFO");
        }

        private void LogMessage(string message, string level = "INFO")
        {
            Dispatcher.Invoke(() =>
            {
                var timestamp = DateTime.Now.ToString("HH:mm:ss");
                var logEntry = $"[{timestamp}] [{level}] {message}\n";
                LogBox.Text += logEntry;

                // Keep only last 500 lines
                var lines = LogBox.Text.Split('\n');
                if (lines.Length > 500)
                {
                    LogBox.Text = string.Join("\n", lines.Skip(lines.Length - 500));
                }
            });
        }

        private void OnStatusChanged(BotStatus status)
        {
            Dispatcher.Invoke(() =>
            {
                Status.Text = $"●  {status.State}";
                Status.Foreground = status.IsConnected 
                    ? System.Windows.Media.Brushes.LimeGreen 
                    : System.Windows.Media.Brushes.Red;
            });
        }

        private void OnRunCompleted(RunStatistics stats)
        {
            Dispatcher.Invoke(() =>
            {
                RunCount.Text = stats.TotalRuns.ToString();
                ItemCount.Text = stats.TotalItems.ToString();
                Uptime.Text = stats.Uptime.ToString(@"hh\:mm\:ss");
                AvgTime.Text = stats.AverageRunTime.ToString(@"mm\:ss");
            });
        }
    }
}

