using System;
using System.Runtime.InteropServices;

namespace D2RBot.GUI.Services
{
    public enum BotState
    {
        Idle,
        Connecting,
        Running,
        Paused,
        Stopping
    }

    public class BotStatus
    {
        public BotState State { get; set; }
        public bool IsConnected { get; set; }
        public DateTime LastUpdate { get; set; }
    }

    public class RunStatistics
    {
        public int TotalRuns { get; set; }
        public int TotalItems { get; set; }
        public TimeSpan Uptime { get; set; }
        public TimeSpan AverageRunTime { get; set; }
    }

    public class BotEngine
    {
        // P/Invoke for C++ DLL
        [DllImport("D2RBot.Engine.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern bool InitializeBot();

        [DllImport("D2RBot.Engine.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern bool StartBotEngine(string route);

        [DllImport("D2RBot.Engine.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern bool StopBotEngine();

        [DllImport("D2RBot.Engine.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern int GetBotStatus();

        [DllImport("D2RBot.Engine.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern void GetGameState(out IntPtr playerPos, out IntPtr nearbyMobs);

        public event Action<string, string> OnLogMessage;
        public event Action<BotStatus> OnStatusChanged;
        public event Action<RunStatistics> OnRunCompleted;

        private BotStatus _currentStatus;
        private RunStatistics _statistics;
        private Timer _statusTimer;
        private bool _isRunning;

        public BotEngine()
        {
            _currentStatus = new BotStatus { State = BotState.Idle, IsConnected = false };
            _statistics = new RunStatistics();
        }

        public void Start(string route)
        {
            try
            {
                if (!InitializeBot())
                {
                    OnLogMessage?.Invoke("Failed to initialize bot engine", "ERROR");
                    return;
                }

                if (!StartBotEngine(route))
                {
                    OnLogMessage?.Invoke("Failed to start bot engine", "ERROR");
                    return;
                }

                _isRunning = true;
                _currentStatus.State = BotState.Running;
                _currentStatus.IsConnected = true;
                OnStatusChanged?.Invoke(_currentStatus);

                _statusTimer = new Timer(_ => UpdateStatus(), null, TimeSpan.Zero, TimeSpan.FromSeconds(1));
                OnLogMessage?.Invoke($"Bot engine initialized and started on route: {route}", "INFO");
            }
            catch (DllNotFoundException)
            {
                OnLogMessage?.Invoke("D2RBot.Engine.dll not found. Make sure the C++ DLL is compiled and in the output directory.", "ERROR");
            }
            catch (Exception ex)
            {
                OnLogMessage?.Invoke($"Error starting bot: {ex.Message}", "ERROR");
            }
        }

        public void Stop()
        {
            try
            {
                _statusTimer?.Dispose();
                StopBotEngine();
                _isRunning = false;
                _currentStatus.State = BotState.Idle;
                _currentStatus.IsConnected = false;
                OnStatusChanged?.Invoke(_currentStatus);
                OnLogMessage?.Invoke("Bot stopped", "INFO");
            }
            catch (Exception ex)
            {
                OnLogMessage?.Invoke($"Error stopping bot: {ex.Message}", "ERROR");
            }
        }

        private void UpdateStatus()
        {
            try
            {
                var status = GetBotStatus();
                GetGameState(out var playerPos, out var mobs);

                OnRunCompleted?.Invoke(_statistics);
            }
            catch (Exception ex)
            {
                OnLogMessage?.Invoke($"Status update error: {ex.Message}", "ERROR");
            }
        }
    }
}

