    : m_processHandle(nullptr), m_processId(0), m_isRunning(false), m_isInitialized(false), m_baseAddress(nullptr)
{
}

BotEngine::~BotEngine()
{
    Stop();
    if (m_processHandle)
    {
        CloseHandle(m_processHandle);
    }
