bool BotEngine::Initialize()
{
    if (m_isInitialized)
        return true;

    if (!FindGameProcess())
    {
        return false;
    }

    if (!AttachToProcess(m_processId))
    {
        return false;
    }

    m_isInitialized = true;
    return true;
}

bool BotEngine::FindGameProcess()
{
    PROCESSENTRY32 pe32;
    pe32.dwSize = sizeof(PROCESSENTRY32);

    HANDLE hProcessSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (hProcessSnap == INVALID_HANDLE_VALUE)
        return false;

    // Look for Diablo II: Resurrected
    if (Process32First(hProcessSnap, &pe32))
    {
        do
        {
            if (_strcmpi(pe32.szExeFile, "D2R.exe") == 0)
            {
                m_processId = pe32.th32ProcessID;
                CloseHandle(hProcessSnap);
                return true;
            }
        } while (Process32Next(hProcessSnap, &pe32));
    }

    CloseHandle(hProcessSnap);
    return false;
}

bool BotEngine::AttachToProcess(DWORD processId)
{
    m_processHandle = OpenProcess(
        PROCESS_ALL_ACCESS,
        FALSE,
        processId
    );

    return m_processHandle != nullptr;
}

